body:
Performance benchmarked, no across-the-board regressions nor improvements found. 

compiled with `scons platform=windows target=editor use_llvm=yes tests=yes -j10`

> AI Disclaimer: AI wrote all the code

Results above their own noise level are reported first and highlighted in the tables. Everything else falls within noise level. 

<details>
<summary> test_user_bench.cpp </summary>

```cpp
#include "tests/test_macros.h"

TEST_FORCE_LINK(test_user_bench)

#include "core/object/callable_mp.h"
#include "core/object/class_db.h"
#include "core/object/method_bind.h"
#include "core/object/object.h"
#include "core/variant/variant.h"
#include "core/variant/variant_internal.h"

#include <algorithm>
#include <chrono>
#include <cstdio>

// Method-calling benchmark.
//
// Covers the call paths touched by:
//   2c0d40c2c0 Simplify `binder_common.h`
//   20e248d90c Simplify `variant_call.cpp`
//   837e8bcc92 Simplify `method_bind_common.h`
//
// Only APIs that exist both before and after those commits are used, so this
// same file can be built at 232e6b14ab (baseline) and at HEAD and the output
// diffed. Always compare identical build configs (target, optimize, lto, ...).
//
// Usage: `godot --test user-bench`

namespace TestUserBench {

class BenchObject : public Object {
	GDCLASS(BenchObject, Object);

protected:
	static void _bind_methods() {
		ClassDB::bind_method(D_METHOD("m0"), &BenchObject::m0);
		ClassDB::bind_method(D_METHOD("m1", "a"), &BenchObject::m1);
		ClassDB::bind_method(D_METHOD("m3", "a", "b", "c"), &BenchObject::m3);
		ClassDB::bind_method(D_METHOD("m6", "a", "b", "c", "d", "e", "f"), &BenchObject::m6);
		ClassDB::bind_method(D_METHOD("cm2", "a", "b"), &BenchObject::cm2);
		ClassDB::bind_method(D_METHOD("v2", "a", "b"), &BenchObject::v2);
		ClassDB::bind_method(D_METHOD("vec", "a", "b"), &BenchObject::vec);
		ClassDB::bind_method(D_METHOD("str", "s"), &BenchObject::str);
		ClassDB::bind_method(D_METHOD("d3", "a", "b", "c"), &BenchObject::d3, DEFVAL(1), DEFVAL(2));
		ClassDB::bind_static_method("BenchObject", D_METHOD("s2", "a", "b"), &BenchObject::s2);
	}

public:
	int64_t acc = 0;

	void m0() { acc++; }
	int m1(int p_a) { return p_a + 1; }
	int m3(int p_a, int p_b, int p_c) { return p_a + p_b + p_c; }
	int m6(int p_a, int p_b, int p_c, int p_d, int p_e, int p_f) { return p_a + 2 * p_b + 3 * p_c + 4 * p_d + 5 * p_e + 6 * p_f; }
	int cm2(int p_a, int p_b) const { return p_a * p_b; }
	void v2(int p_a, int p_b) { acc += p_a ^ p_b; }
	Vector3 vec(const Vector3 &p_a, const Vector3 &p_b) const { return p_a + p_b; }
	String str(const String &p_s) const { return p_s; }
	int d3(int p_a, int p_b, int p_c) { return p_a * 100 + p_b * 10 + p_c; }
	static int s2(int p_a, int p_b) { return p_a - p_b; }
};

static constexpr int ITERS = 1'000'000;
static constexpr int SAMPLES = 9;
static uint64_t sink = 0; // Defeats dead-code elimination.

// Validated calls write the result straight into the Variant's storage without touching its
// type tag. Callers (e.g. the GDScript VM) pre-initialize the return slot to the right type,
// so the benchmark has to do the same.
static Variant typed_ret(Variant::Type p_type) {
	Variant v;
	VariantInternal::initialize(&v, p_type);
	return v;
}

static void section(const char *p_title) {
	printf("\n== %s\n", p_title);
}

// Reports min, median and spread of SAMPLES timed batches.
// spread = (max - min) / median, as a percentage: this is the noise level of the run.
template <typename F>
static void run(const char *p_name, F &&p_fn, int p_iters = ITERS) {
	for (int i = 0; i < p_iters / 10; i++) { // Warmup.
		p_fn();
	}

	double samples[SAMPLES];
	for (int s = 0; s < SAMPLES; s++) {
		auto t0 = std::chrono::steady_clock::now();
		for (int i = 0; i < p_iters; i++) {
			p_fn();
		}
		auto t1 = std::chrono::steady_clock::now();
		samples[s] = std::chrono::duration<double, std::nano>(t1 - t0).count() / p_iters;
	}
	std::sort(samples, samples + SAMPLES);
	const double median = samples[SAMPLES / 2];
	const double spread = (samples[SAMPLES - 1] - samples[0]) / median * 100.0;
	printf("  %-46s min %8.2f   med %8.2f   spread %6.2f%%\n", p_name, samples[0], median, spread);
}

static int user_bench() {
	setvbuf(stdout, nullptr, _IONBF, 0); // Keep partial output if something crashes.
	ClassDB::register_class<BenchObject>();
	BenchObject *obj = memnew(BenchObject);
	const StringName cls = "BenchObject";

#define GET_BIND(m_var, m_name) \
	const MethodBind *m_var = ClassDB::get_method(cls, m_name); \
	if (!m_var) { \
		printf("Missing method bind '%s'.\n", m_name); \
		memdelete(obj); \
		return 1; \
	}

	GET_BIND(mb_m0, "m0");
	GET_BIND(mb_m1, "m1");
	GET_BIND(mb_m3, "m3");
	GET_BIND(mb_m6, "m6");
	GET_BIND(mb_cm2, "cm2");
	GET_BIND(mb_v2, "v2");
	GET_BIND(mb_vec, "vec");
	GET_BIND(mb_str, "str");
	GET_BIND(mb_d3, "d3");
	GET_BIND(mb_s2, "s2");
#undef GET_BIND

	// Pre-built arguments, so only the call itself is measured.
	Variant iv[6] = { 7, 3, 5, 1, 2, 4 };
	const Variant *ip[6] = { &iv[0], &iv[1], &iv[2], &iv[3], &iv[4], &iv[5] };
	Variant vec_a = Vector3(1, 2, 3);
	Variant vec_b = Vector3(4, 5, 6);
	const Variant *vec_args[2] = { &vec_a, &vec_b };
	Variant str_a = String("hello world");
	const Variant *str_args[1] = { &str_a };

	// Same arguments in ptrcall form (ints are passed as int64_t, floats as double).
	int64_t pi[6] = { 7, 3, 5, 1, 2, 4 };
	const void *pp[6] = { &pi[0], &pi[1], &pi[2], &pi[3], &pi[4], &pi[5] };
	Vector3 pvec_a(1, 2, 3), pvec_b(4, 5, 6);
	const void *pvec_args[2] = { &pvec_a, &pvec_b };
	String pstr_a = "hello world";
	const void *pstr_args[1] = { &pstr_a };

	Callable::CallError ce;

	Variant vstr = String("hello world");
	Variant vv3 = Vector3(1, 2, 3);
	Variant varr = Array();
	Variant vdict = Dictionary();
	Variant half = 0.5;
	Variant vs_prefix = String("hello");
	Variant vv3_other = Vector3(4, 5, 6);
	Variant vany = 42;

	const Variant *b_none[1] = { nullptr };
	const Variant *b_prefix[1] = { &vs_prefix };
	const Variant *b_v3[1] = { &vv3_other };
	const Variant *b_v3_w[2] = { &vv3_other, &half };
	const Variant *b_any[1] = { &vany };
	const Variant *b_substr[1] = { &iv[3] }; // substr(1), uses the default length.

	// Sanity: verifies both correctness and that every path used below resolves.
	bool ok = true;
	auto expect = [&](bool p_cond, const char *p_what) {
		if (!p_cond) {
			printf("SANITY FAIL: %s\n", p_what);
			ok = false;
		}
	};
	{
		Variant r;
		r = mb_m1->call(obj, ip, 1, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (int)r == 8, "MethodBind::call m1");
		r = mb_m3->call(obj, ip, 3, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (int)r == 15, "MethodBind::call m3");
		r = mb_m6->call(obj, ip, 6, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (int)r == 66, "MethodBind::call m6");
		r = mb_cm2->call(obj, ip, 2, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (int)r == 21, "MethodBind::call cm2");
		r = mb_d3->call(obj, ip, 1, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (int)r == 712, "MethodBind::call d3 (defaults)");
		r = mb_d3->call(obj, ip, 3, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (int)r == 735, "MethodBind::call d3 (all args)");
		r = mb_s2->call(obj, ip, 2, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (int)r == 4, "MethodBind::call s2 (static)");
		r = mb_vec->call(obj, vec_args, 2, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (Vector3)r == Vector3(5, 7, 9), "MethodBind::call vec");
		r = mb_str->call(obj, str_args, 1, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (String)r == "hello world", "MethodBind::call str");

		Variant ri = typed_ret(Variant::INT);
		Variant rv3 = typed_ret(Variant::VECTOR3);
		mb_m3->validated_call(obj, ip, &ri);
		expect((int)ri == 15, "validated_call m3");
		mb_vec->validated_call(obj, vec_args, &rv3);
		expect((Vector3)rv3 == Vector3(5, 7, 9), "validated_call vec");

		int64_t pr = 0;
		mb_m3->ptrcall(obj, pp, &pr);
		expect(pr == 15, "ptrcall m3");
		Vector3 pvr;
		mb_vec->ptrcall(obj, pvec_args, &pvr);
		expect(pvr == Vector3(5, 7, 9), "ptrcall vec");

		r = obj->callp("m3", ip, 3, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (int)r == 15, "Object::callp m3");

		vstr.callp("length", nullptr, 0, r, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (int)r == 11, "String.length");
		vstr.callp("begins_with", b_prefix, 1, r, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (bool)r, "String.begins_with");
		vv3.callp("dot", b_v3, 1, r, ce);
		expect(ce.error == Callable::CallError::CALL_OK && (double)r == 32.0, "Vector3.dot");

		Callable c = callable_mp(obj, &BenchObject::m3);
		r = c.call(7, 3, 5);
		expect((int)r == 15, "callable_mp m3");
		c = callable_mp_static(&BenchObject::s2);
		r = c.call(7, 3);
		expect((int)r == 4, "callable_mp_static s2");

		for (const char *name : { "absf", "lerpf", "snappedf", "max" }) {
			expect(Variant::has_utility_function(name), name);
		}
	}
	if (!ok) {
		memdelete(obj);
		return 1;
	}

	printf("Method call benchmark (%d x %d iterations, ns/op, spread = (max-min)/median)\n", SAMPLES, ITERS);
#ifdef DEBUG_ENABLED
	printf("  build: DEBUG_ENABLED\n");
#else
	printf("  build: release\n");
#endif
#ifdef TOOLS_ENABLED
	printf("  build: TOOLS_ENABLED (placeholder checks active)\n");
#endif

	// ------------------------------------------------------------------
	// method_bind_common.h + binder_common.h
	// ------------------------------------------------------------------
	section("MethodBind::call (Variant args, call_with_variant_args_dv)");
	run("m0()           void", [&] { Variant r = mb_m0->call(obj, ip, 0, ce); sink += r.get_type(); });
	run("m1(int)        -> int", [&] { Variant r = mb_m1->call(obj, ip, 1, ce); sink += r.get_type(); });
	run("m3(int x3)     -> int", [&] { Variant r = mb_m3->call(obj, ip, 3, ce); sink += r.get_type(); });
	run("m6(int x6)     -> int", [&] { Variant r = mb_m6->call(obj, ip, 6, ce); sink += r.get_type(); });
	run("cm2(int x2)    const -> int", [&] { Variant r = mb_cm2->call(obj, ip, 2, ce); sink += r.get_type(); });
	run("v2(int x2)     void", [&] { Variant r = mb_v2->call(obj, ip, 2, ce); sink += r.get_type(); });
	run("vec(Vector3 x2) const -> Vector3", [&] { Variant r = mb_vec->call(obj, vec_args, 2, ce); sink += r.get_type(); });
	run("str(String)    const -> String", [&] { Variant r = mb_str->call(obj, str_args, 1, ce); sink += r.get_type(); });
	run("d3(int) + 2 default args", [&] { Variant r = mb_d3->call(obj, ip, 1, ce); sink += r.get_type(); });
	run("d3(int x3), no defaults used", [&] { Variant r = mb_d3->call(obj, ip, 3, ce); sink += r.get_type(); });
	run("s2(int x2)     static -> int", [&] { Variant r = mb_s2->call(obj, ip, 2, ce); sink += r.get_type(); });

	section("MethodBind::validated_call (call_with_validated_args)");
	{
		Variant r_int = typed_ret(Variant::INT);
		Variant r_v3 = typed_ret(Variant::VECTOR3);
		Variant r_str = typed_ret(Variant::STRING);
		Variant r_void; // Void methods never write the return slot.
		run("m0()           void", [&] { mb_m0->validated_call(obj, ip, &r_void); sink += r_void.get_type(); });
		run("m1(int)        -> int", [&] { mb_m1->validated_call(obj, ip, &r_int); sink += r_int.get_type(); });
		run("m3(int x3)     -> int", [&] { mb_m3->validated_call(obj, ip, &r_int); sink += r_int.get_type(); });
		run("m6(int x6)     -> int", [&] { mb_m6->validated_call(obj, ip, &r_int); sink += r_int.get_type(); });
		run("cm2(int x2)    const -> int", [&] { mb_cm2->validated_call(obj, ip, &r_int); sink += r_int.get_type(); });
		run("v2(int x2)     void", [&] { mb_v2->validated_call(obj, ip, &r_void); sink += r_void.get_type(); });
		run("vec(Vector3 x2) const -> Vector3", [&] { mb_vec->validated_call(obj, vec_args, &r_v3); sink += r_v3.get_type(); });
		run("str(String)    const -> String", [&] { mb_str->validated_call(obj, str_args, &r_str); sink += r_str.get_type(); });
		run("s2(int x2)     static -> int", [&] { mb_s2->validated_call(obj, ip, &r_int); sink += r_int.get_type(); });
	}

	section("MethodBind::ptrcall (call_with_ptr_args)");
	{
		int64_t pr = 0;
		Vector3 pvr;
		String psr;
		run("m0()           void", [&] { mb_m0->ptrcall(obj, pp, nullptr); sink += obj->acc; });
		run("m1(int)        -> int", [&] { mb_m1->ptrcall(obj, pp, &pr); sink += pr; });
		run("m3(int x3)     -> int", [&] { mb_m3->ptrcall(obj, pp, &pr); sink += pr; });
		run("m6(int x6)     -> int", [&] { mb_m6->ptrcall(obj, pp, &pr); sink += pr; });
		run("cm2(int x2)    const -> int", [&] { mb_cm2->ptrcall(obj, pp, &pr); sink += pr; });
		run("v2(int x2)     void", [&] { mb_v2->ptrcall(obj, pp, nullptr); sink += obj->acc; });
		run("vec(Vector3 x2) const -> Vector3", [&] { mb_vec->ptrcall(obj, pvec_args, &pvr); sink += (uint64_t)pvr.x; });
		run("str(String)    const -> String", [&] { mb_str->ptrcall(obj, pstr_args, &psr); sink += psr.length(); });
		run("s2(int x2)     static -> int", [&] { mb_s2->ptrcall(obj, pp, &pr); sink += pr; });
	}

	section("Object::callp by name (ClassDB lookup + MethodBind::call)");
	{
		const StringName n_m1 = "m1", n_m3 = "m3";
		run("m1(int)        -> int", [&] { Variant r = obj->callp(n_m1, ip, 1, ce); sink += r.get_type(); });
		run("m3(int x3)     -> int", [&] { Variant r = obj->callp(n_m3, ip, 3, ce); sink += r.get_type(); });
	}

	// ------------------------------------------------------------------
	// variant_call.cpp
	// ------------------------------------------------------------------
	section("Variant::callp builtin methods (name lookup + call)");
	{
		const StringName n_length = "length", n_begins = "begins_with", n_substr = "substr";
		const StringName n_dot = "dot", n_lerp = "lerp", n_size = "size", n_has = "has";
		Variant r;
		run("String.length()", [&] { vstr.callp(n_length, nullptr, 0, r, ce); sink += r.get_type(); });
		run("String.begins_with(String)", [&] { vstr.callp(n_begins, b_prefix, 1, r, ce); sink += r.get_type(); });
		run("String.substr(int) + default arg", [&] { vstr.callp(n_substr, b_substr, 1, r, ce); sink += r.get_type(); });
		run("Vector3.dot(Vector3)", [&] { vv3.callp(n_dot, b_v3, 1, r, ce); sink += r.get_type(); });
		run("Vector3.lerp(Vector3, float)", [&] { vv3.callp(n_lerp, b_v3_w, 2, r, ce); sink += r.get_type(); });
		run("Array.size()", [&] { varr.callp(n_size, nullptr, 0, r, ce); sink += r.get_type(); });
		run("Array.has(Variant)", [&] { varr.callp(n_has, b_any, 1, r, ce); sink += r.get_type(); });
		run("Dictionary.has(Variant)", [&] { vdict.callp(n_has, b_any, 1, r, ce); sink += r.get_type(); });
	}

	section("Variant validated builtin methods");
	{
		auto vl_length = Variant::get_validated_builtin_method(Variant::STRING, "length");
		auto vl_begins = Variant::get_validated_builtin_method(Variant::STRING, "begins_with");
		auto vl_dot = Variant::get_validated_builtin_method(Variant::VECTOR3, "dot");
		auto vl_lerp = Variant::get_validated_builtin_method(Variant::VECTOR3, "lerp");
		auto vl_size = Variant::get_validated_builtin_method(Variant::ARRAY, "size");
		auto vl_has = Variant::get_validated_builtin_method(Variant::ARRAY, "has");
		if (!vl_length || !vl_begins || !vl_dot || !vl_lerp || !vl_size || !vl_has) {
			printf("Missing validated builtin method.\n");
			memdelete(obj);
			return 1;
		}
		Variant r_int = typed_ret(Variant::INT);
		Variant r_bool = typed_ret(Variant::BOOL);
		Variant r_float = typed_ret(Variant::FLOAT);
		Variant r_v3 = typed_ret(Variant::VECTOR3);
		run("String.length()", [&] { vl_length(&vstr, b_none, 0, &r_int); sink += r_int.get_type(); });
		run("String.begins_with(String)", [&] { vl_begins(&vstr, b_prefix, 1, &r_bool); sink += r_bool.get_type(); });
		run("Vector3.dot(Vector3)", [&] { vl_dot(&vv3, b_v3, 1, &r_float); sink += r_float.get_type(); });
		run("Vector3.lerp(Vector3, float)", [&] { vl_lerp(&vv3, b_v3_w, 2, &r_v3); sink += r_v3.get_type(); });
		run("Array.size()", [&] { vl_size(&varr, b_none, 0, &r_int); sink += r_int.get_type(); });
		run("Array.has(Variant)", [&] { vl_has(&varr, b_any, 1, &r_bool); sink += r_bool.get_type(); });
	}

	section("Variant ptr builtin methods");
	{
		auto pt_length = Variant::get_ptr_builtin_method(Variant::STRING, "length");
		auto pt_begins = Variant::get_ptr_builtin_method(Variant::STRING, "begins_with");
		auto pt_dot = Variant::get_ptr_builtin_method(Variant::VECTOR3, "dot");
		auto pt_lerp = Variant::get_ptr_builtin_method(Variant::VECTOR3, "lerp");
		auto pt_size = Variant::get_ptr_builtin_method(Variant::ARRAY, "size");
		auto pt_has = Variant::get_ptr_builtin_method(Variant::ARRAY, "has");
		if (!pt_length || !pt_begins || !pt_dot || !pt_lerp || !pt_size || !pt_has) {
			printf("Missing ptr builtin method.\n");
			memdelete(obj);
			return 1;
		}
		String s = "hello world";
		String prefix = "hello";
		Vector3 v(1, 2, 3), other(4, 5, 6), vr;
		double weight = 0.5;
		Array arr;
		Variant any = 42;
		alignas(16) uint8_t rb[64] = {};
		const void *no_args[1] = { nullptr };
		const void *a_prefix[1] = { &prefix };
		const void *a_other[1] = { &other };
		const void *a_lerp[2] = { &other, &weight };
		const void *a_any[1] = { &any };
		run("String.length()", [&] { pt_length(&s, no_args, rb, 0); sink += rb[0]; });
		run("String.begins_with(String)", [&] { pt_begins(&s, a_prefix, rb, 1); sink += rb[0]; });
		run("Vector3.dot(Vector3)", [&] { pt_dot(&v, a_other, rb, 1); sink += rb[0]; });
		run("Vector3.lerp(Vector3, float)", [&] { pt_lerp(&v, a_lerp, &vr, 2); sink += (uint64_t)vr.x; });
		run("Array.size()", [&] { pt_size(&arr, no_args, rb, 0); sink += rb[0]; });
		run("Array.has(Variant)", [&] { pt_has(&arr, a_any, rb, 1); sink += rb[0]; });
	}

	section("Variant utility functions");
	{
		const StringName n_absf = "absf", n_lerpf = "lerpf", n_snappedf = "snappedf", n_max = "max";
		Variant fa = -3.5, fb = 10.0, fc = 0.25, fd = 3, fe = 9;
		const Variant *u1[1] = { &fa };
		const Variant *u2[2] = { &fa, &fb };
		const Variant *u3[3] = { &fa, &fb, &fc };
		const Variant *u_max[2] = { &fd, &fe };
		Variant r;
		run("call_utility_function absf(float)", [&] { Variant::call_utility_function(n_absf, &r, u1, 1, ce); sink += r.get_type(); });
		run("call_utility_function snappedf(float x2)", [&] { Variant::call_utility_function(n_snappedf, &r, u2, 2, ce); sink += r.get_type(); });
		run("call_utility_function lerpf(float x3)", [&] { Variant::call_utility_function(n_lerpf, &r, u3, 3, ce); sink += r.get_type(); });
		run("call_utility_function max(vararg x2)", [&] { Variant::call_utility_function(n_max, &r, u_max, 2, ce); sink += r.get_type(); });

		auto vu_absf = Variant::get_validated_utility_function(n_absf);
		auto vu_lerpf = Variant::get_validated_utility_function(n_lerpf);
		auto pu_absf = Variant::get_ptr_utility_function(n_absf);
		auto pu_lerpf = Variant::get_ptr_utility_function(n_lerpf);
