# GDScript method-call benchmark: how the method call paths feel to users.
#
# Companion to the C++ benchmark (tests/core/test_user_bench.cpp). It exercises the
# call paths touched by:
#   2c0d40c2c0 Simplify `binder_common.h`
#   20e248d90c Simplify `variant_call.cpp`
#   837e8bcc92 Simplify `method_bind_common.h`
# but through GDScript, so the numbers include the VM's own dispatch. Typed variables
# take the VM's fast paths (validated / ptrcall opcodes); untyped (Variant) ones take the
# dynamic path (Variant::callp / Object::callp -> MethodBind::call).
#
# The output format matches the C++ benchmark, so compare_user_bench.py works on it.
#
# Usage (same binary type for both builds, e.g. from each worktree's root):
#   godot --headless --script <path>/user_bench.gd > out.txt
# Optional user args after `--`:
#   --raw    don't subtract the empty-loop overhead
#   --dump   print the generated benchmark source and exit
#
# How it works: every row below is turned into a small typed GDScript function of the form
#   <setup>; for _i in range(n): <statement>; <teardown>
# which is compiled by the engine like any user script. Each row's time is the min / median
# of SAMPLES batches, minus the cost of an empty loop (so the numbers are per call and
# not per loop iteration), reported in ns/op with spread = (max - min) / median.
#
# Note: callable_mp (C++-only) isn't reachable from GDScript; it is covered by the C++ bench.

const ITERS := 1_000_000
const SAMPLES := 9
const MIN_NS := 0.01 # Floor after loop-overhead subtraction, keeps ratios finite.

const PRELUDE := "extends RefCounted\n\nfunc _ctl(x: int) -> int:\n\treturn x + 1\n\n"

# Row = [section, name, setup, statement, expected_result_of_one_iteration (or null), teardown, iteration_divisor].
