	_add(NT, "Node.get_name()  0 args -> StringName", node_setup + "var nm: StringName\n", "nm = n.get_name()", 0, "n.free()")
	_add(NT, "Object.is_class(String)  1 arg -> bool", node_setup + "var cls := \"Node3D\"\n", "if n.is_class(cls):\n\tacc += 1", 1, "n.free()")
