			+ "var c_id := Callable(n, nm)\nvar c_sp := Callable(n, sp)\nvar c_rf := Callable(rng, &\"randf_range\")\nvar c_bound := c_rf.bind(lo)\n"
	_add(CA, "Object.call(&\"get_instance_id\")", call_setup, "res = n.call(nm)", null, "n.free()")
	_add(CA, "Object.call(&\"set_position\", v)", call_setup, "n.call(sp, v)", 0, "n.free()")
	_add(CA, "Object.callv(&\"set_position\", [v])", call_setup, "n.callv(sp, args)", 0, "n.free()")
	_add(CA, "Callable(obj, \"get_instance_id\").call()", cb_setup, "res = c_id.call()", null, "n.free()")
	_add(CA, "Callable(obj, \"set_position\").call(v)", cb_setup, "c_sp.call(v)", 0, "n.free()")
	_add(CA, "Callable(rng, \"randf_range\").call(lo, hi)", cb_setup, "res = c_rf.call(lo, hi)", null, "n.free()")
	_add(CA, "Callable(rng, \"randf_range\").callv([lo, hi])", cb_setup, "res = c_rf.callv(rargs)", null, "n.free()")
	_add(CA, "Callable.bind(lo).call(hi)", cb_setup, "res = c_bound.call(hi)", null, "n.free()")

	# --- Builtin-type methods, typed: OPCODE_CALL_BUILTIN_TYPE_VALIDATED. ---
	var BT := "GDScript builtin methods, typed (validated)"
