func _indent(p_text: String, p_tabs: int) -> String:
	if p_text.is_empty():
		return ""
	var prefix := "\t".repeat(p_tabs)
	var out := ""
	for line in p_text.strip_edges(false, true).split("\n"):
		out += prefix + line + "\n"
	return out


func _generate() -> String:
	var src := PRELUDE
	for i in rows.size():
		var r: Array = rows[i]
		src += "func b%d(n_iters: int) -> int:\n" % i
		src += "\tvar acc := 0\n\tvar facc := 0.0\n"
		src += _indent(r[2], 1)
		src += "\tfor _i in range(n_iters):\n"
		src += _indent(r[3], 2)
		src += _indent(r[5], 1)
		src += "\treturn acc + int(facc)\n\n"
	return src


func _measure(p_inst: Object, p_fn: StringName, p_iters: int) -> Array[float]:
	sink += int(p_inst.call(p_fn, maxi(p_iters / 10, 1))) # Warmup.
	var samples: Array[float] = []
	for _s in SAMPLES:
		var t0 := Time.get_ticks_usec()
		sink += int(p_inst.call(p_fn, p_iters))
		var t1 := Time.get_ticks_usec()
		samples.append(float(t1 - t0) * 1000.0 / p_iters)
	samples.sort()
	return samples


func _report(p_name: String, p_samples: Array[float], p_subtract: float) -> void:
	var s: Array[float] = []
	for x in p_samples:
		s.append(maxf(x - p_subtract, MIN_NS))
	var median := s[SAMPLES / 2]
	var spread := (s[SAMPLES - 1] - s[0]) / median * 100.0
	print("  %-46s min %8.2f   med %8.2f   spread %6.2f%%" % [p_name, s[0], median, spread])


func _fail(p_message: String) -> void:
	print("SANITY FAIL: ", p_message)
	quit(1)


func _init() -> void:
	var user_args := OS.get_cmdline_user_args()
	var raw := "--raw" in user_args

	_build_rows()
	var source := _generate()
	if "--dump" in user_args:
		print(source)
		quit()
		return

	var gd := GDScript.new()
	gd.source_code = source
	var err := gd.reload()
	if err != OK:
		_fail("generated benchmark script failed to compile (error %d); rerun with -- --dump to inspect it" % err)
		return
	var inst: Object = gd.new()

	# Sanity: one iteration of each row must produce the expected result.
	for i in rows.size():
		var r: Array = rows[i]
		var result := int(inst.call("b%d" % i, 1))
		if r[4] != null and result != int(r[4]):
			_fail("[%s] %s: expected %s, got %d" % [r[0], r[1], str(r[4]), result])
			return

	print("GDScript method call benchmark (%d x %d iterations, ns/op, spread = (max-min)/median)" % [SAMPLES, ITERS])
	var build_kind := "debug" if OS.is_debug_build() else "release"
	print("  build: %s, %s" % [build_kind, "editor" if OS.has_feature("editor") else "template"])
	print("  loop overhead %s" % ("NOT subtracted (--raw)" if raw else "subtracted from every row below the first"))

	var overhead := 0.0
	var section := ""
	for i in rows.size():
		var r: Array = rows[i]
		if r[0] != section:
			section = r[0]
			print("\n== %s" % section)
		var samples := _measure(inst, "b%d" % i, ITERS / int(r[6]))
		if i == 0:
			# Baseline row: shown raw, then used as the overhead for all others.
			overhead = 0.0 if raw else samples[0]
			_report(r[1], samples, 0.0)
		else:
			_report(r[1], samples, overhead)

	print("\n(sink %d)" % sink)
	quit()
