```py
#!/usr/bin/env python3
"""Compare two `godot --test user-bench` outputs.

Usage: compare_user_bench.py base.txt head.txt [options] > summary.md

By default the output is GitHub-flavored markdown, ready to paste into a PR
description. Use --plain for a fixed-width text table instead.

For every benchmark row:
  ratio = head_min / base_min          (head = PR, base = master)
  delta = ratio - 1                    (shown as a percentage)
  noise = worse (larger) of the two binaries' spreads, where
          spread = (max - min) / median across the rounds.

A row is only called a regression / improvement when |delta| exceeds its noise
level (and --min-delta, default 0); otherwise it is "~" (within noise).
Exit code is 1 if any regression is found.
"""

import argparse
import re
import sys

ROW = re.compile(r"^\s{2}(.+?)\s+min\s+([\d.]+)\s+med\s+([\d.]+)\s+spread\s+([\d.]+)%\s*$")

REGRESSION = "regression"
IMPROVEMENT = "improvement"
NOISE = "~"


def parse(path):
    rows = {}
    order = []
    section = ""
    with open(path, "rb") as f:
        raw = f.read()
    # PowerShell 5 redirects (`>`) produce UTF-16 with a BOM; everything else is UTF-8.
    if raw.startswith((b"\xff\xfe", b"\xfe\xff")):
        text = raw.decode("utf-16", errors="replace")
    else:
        text = raw.decode("utf-8-sig", errors="replace")
    for line in text.splitlines():
        if line.startswith("SANITY FAIL") or line.startswith("Missing "):
            sys.exit(f"{path}: {line}")
        if line.startswith("== "):
            section = line[3:].strip()
            continue
        m = ROW.match(line)
        if m:
            key = (section, re.sub(r"\s+", " ", m.group(1).strip()))
            rows[key] = tuple(float(m.group(i)) for i in (2, 3, 4))  # min, med, spread
            order.append(key)
    if not rows:
        sys.exit(f"{path}: no benchmark rows found")
    return rows, order


def compare(base, head, order, min_delta):
    """Returns a list of (section, name, base_min, head_min, delta, noise, verdict)."""
    results = []
    for key in order:
        if key not in head:
            continue
        b_min, _, b_spread = base[key]
        h_min, _, h_spread = head[key]
        delta = (h_min - b_min) / b_min * 100.0
        noise = max(b_spread, h_spread)
        threshold = max(noise, min_delta)
        if delta > threshold:
            verdict = REGRESSION
        elif delta < -threshold:
            verdict = IMPROVEMENT
        else:
            verdict = NOISE
        results.append((key[0], key[1], b_min, h_min, delta, noise, verdict))
    return results


def summary_line(results):
    regressions = sum(1 for r in results if r[6] == REGRESSION)
    improvements = sum(1 for r in results if r[6] == IMPROVEMENT)
    max_noise = max((r[5] for r in results), default=0.0)
    return regressions, improvements, max_noise


def md_cell(text):
    return text.replace("|", "\\|")


def render_markdown(results, missing_head, missing_base, opts):
    regressions, improvements, max_noise = summary_line(results)
    out = []
    out.append("### Method call benchmark")
    out.append("")
    out.append(
        f"**{regressions}** regression(s), **{improvements}** improvement(s), "
        f"{len(results)} benchmarks compared. Worst noise: {max_noise:.1f}%."
    )
    out.append("")

    for title, verdict in ("Regressions", REGRESSION), ("Improvements", IMPROVEMENT):
        flagged = [r for r in results if r[6] == verdict]
        if not flagged:
            continue
        flagged.sort(key=lambda r: abs(r[4]), reverse=True)  # Largest change first.
        out.append(f"**{title}:**")
        out.append("")
        for section, name, b, h, delta, noise, _ in flagged:
            out.append(
                f"- `{md_cell(name)}` ({section}): {b:.2f} -> {h:.2f} ns/op, "
                f"ratio {h / b:.3f}, **{delta:+.1f}%** (noise {noise:.1f}%)"
            )
        out.append("")

    section = None
    for sec, name, b, h, delta, noise, verdict in results:
        if sec != section:
            if section is not None:
                out.append("")
            section = sec
            out.append(f"#### {sec}")
            out.append("")
            out.append(
                f"| Benchmark | {opts.base_label} | {opts.head_label} | Ratio ({opts.head_label}/{opts.base_label}) | Delta (ratio-1) | Noise |"
            )
            out.append("|---|---:|---:|---:|---:|---:|")
        ratio = h / b
        delta_cell = f"{delta:+.1f}%"
        if verdict == REGRESSION:
            delta_cell = f"**{delta_cell}** :red_circle:"
        elif verdict == IMPROVEMENT:
            delta_cell = f"**{delta_cell}** :green_circle:"
        out.append(f"| `{md_cell(name)}` | {b:.2f} | {h:.2f} | {ratio:.3f} | {delta_cell} | {noise:.1f}% |")

    for label, keys in ((opts.head_label, missing_head), (opts.base_label, missing_base)):
        if keys:
            out.append("")
            out.append(f"Rows missing from **{label}**: " + ", ".join(f"`{md_cell(k[1])}`" for k in keys))

    out.append("")
    out.append(
        f"Times are ns/op, taken from the fastest of the rounds (min). Ratio is {opts.head_label}/{opts.base_label}, "
        f"so above 1 means slower. Noise is the worse of the two builds' spread, `(max - min) / median` across "
        "rounds. A row is only marked when |delta| exceeds its noise"
        + (f" and {opts.min_delta:g}%" if opts.min_delta else "")
        + "."
    )
    out[-1] = "<sub>" + out[-1] + "</sub>"
    return "\n".join(out)


def render_plain(results, missing_head, missing_base, opts):
    regressions, improvements, max_noise = summary_line(results)
    out = [f"{'benchmark':<48} {opts.base_label:>9} {opts.head_label:>9} {'ratio':>7} {'delta':>8} {'noise':>7}  verdict"]
    section = None
    for sec, name, b, h, delta, noise, verdict in results:
        if sec != section:
            section = sec
            out.append(f"\n== {sec}")
        shown = {REGRESSION: "REGRESSION", IMPROVEMENT: "improvement", NOISE: "~"}[verdict]
        out.append(f"  {name:<46} {b:9.2f} {h:9.2f} {h / b:7.3f} {delta:+7.1f}% {noise:6.1f}%  {shown}")
    for k in missing_head:
        out.append(f"{k[1]:<48} missing in {opts.head_label}")
    for k in missing_base:
        out.append(f"{k[1]:<48} missing in {opts.base_label}")
    out.append(f"\n{regressions} regression(s), {improvements} improvement(s), {len(results)} rows; worst noise {max_noise:.1f}%")
    return "\n".join(out)


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("base")
    parser.add_argument("head")
    parser.add_argument("--min-delta", type=float, default=0.0, help="extra minimum %% change required to flag a row")
    parser.add_argument("--plain", action="store_true", help="fixed-width text instead of markdown")
    parser.add_argument("--base-label", default="master", help="name of the baseline build (column title)")
    parser.add_argument("--head-label", default="PR", help="name of the new build (column title)")
    opts = parser.parse_args()

    base, order = parse(opts.base)
    head, head_order = parse(opts.head)

    results = compare(base, head, order, opts.min_delta)
    missing_head = [k for k in order if k not in head]
    missing_base = [k for k in head_order if k not in base]

    render = render_plain if opts.plain else render_markdown
    print(render(results, missing_head, missing_base, opts))

    sys.exit(1 if any(r[6] == REGRESSION for r in results) else 0)


if __name__ == "__main__":
    main()
